parentPath = str(self.view.params.Tag_Path_0)

if not parentPath:
    return

# Get all UDT instances under COR001
results = system.tag.browse(
    parentPath,
    {
        "tagType": "UdtInstance"
    }
)

udtInstances = list(results.getResults())

# Process every UDT instance sequentially
for index, udt in enumerate(udtInstances):

    udtPath = str(udt["fullPath"])

    # Browse attributes inside the UDT
    childResults = system.tag.browse(udtPath)

    parameterData = []

    tagPaths = []
    tagNames = []

    for child in childResults.getResults():

        if str(child["tagType"]) == "AtomicTag":

            tagNames.append(str(child["name"]))
            tagPaths.append(str(child["fullPath"]))

    # Read all attribute values
    if tagPaths:

        values = system.tag.readBlocking(tagPaths)

        for i in range(len(tagPaths)):

            parameterData.append({
                "Parameter": tagNames[i],
                "Value": values[i].value
            })

    # Store sequentially
    propertyName = "parameterData_" + str(index)

    self.view.custom[propertyName] = parameterData
